import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.0AV_2kjq.js";const p=JSON.parse('{"title":"Privacy Policy","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://moviplayer.com/docs/privacy-policy"}]]},"headers":[],"relativePath":"privacy-policy.md","filePath":"privacy-policy.md"}'),s={name:"privacy-policy.md"};function i(n,e,l,d,c,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to &quot;Privacy Policy&quot;">​</a></h1><p><strong>Last updated:</strong> August 19, 2026</p><p><strong>Movi Player — Web Player, Chrome Extension &amp; Google Drive integration</strong></p><p>Movi Player is an open-source video player. Your privacy matters to us, and Movi Player is designed so that your video files stay on your device.</p><h2 id="what-we-do-not-do" tabindex="-1">What We Do Not Do <a class="header-anchor" href="#what-we-do-not-do" aria-label="Permalink to &quot;What We Do Not Do&quot;">​</a></h2><ul><li><strong>No analytics or tracking</strong> — We use no analytics services, tracking pixels, or telemetry.</li><li><strong>No user accounts</strong> — Movi Player requires no sign-up or authentication.</li><li><strong>No cookies</strong> — We set and read no cookies.</li><li><strong>No advertising</strong> — We run no ads and share no data with advertisers or data brokers.</li><li><strong>We never see your video</strong> — No file you play is uploaded to us, stored by us, or inspected by us.</li></ul><h2 id="video-playback" tabindex="-1">Video Playback <a class="header-anchor" href="#video-playback" aria-label="Permalink to &quot;Video Playback&quot;">​</a></h2><p><strong>Local files.</strong> A file you drag in or pick from your device is read entirely in your browser. It is never uploaded anywhere.</p><p><strong>Google Drive files.</strong> These stream directly from Google&#39;s servers to your browser.</p><p><strong>URLs you paste.</strong> Movi Player normally fetches the video straight from the host you named — the request goes from your browser to that host, and we are not involved.</p><p>Some hosts do not send the cross-origin headers a browser requires for playback. In that case only, the request is routed through a fetch relay we operate so the bytes can reach your player. When that happens:</p><ul><li>The relay <strong>streams bytes through and stores nothing</strong> — no caching, no recording, no copy retained.</li><li>We do not log the URLs you play, and we do not build any profile of what you watch.</li><li>Your IP address is visible to Cloudflare, which serves this site, as it is for any website you visit.</li><li><strong>Embedded players (<code>/embed</code>) never use the relay</strong> — they always load from the source host directly.</li></ul><h2 id="visitor-comments" tabindex="-1">Visitor Comments <a class="header-anchor" href="#visitor-comments" aria-label="Permalink to &quot;Visitor Comments&quot;">​</a></h2><p>If you post in the feedback section on moviplayer.com, we store what you submit: the display name you type, your comment text, an optional rating, and a timestamp. Comments are public.</p><p>We also store a <strong>salted, truncated one-way hash of your IP address</strong> solely to rate-limit spam. The hash cannot be reversed to recover your IP, and your actual IP address is never written to our database.</p><p>Comments are stored in Cloudflare D1. To have a comment you posted removed, email the address at the bottom of this page.</p><h2 id="local-storage" tabindex="-1">Local Storage <a class="header-anchor" href="#local-storage" aria-label="Permalink to &quot;Local Storage&quot;">​</a></h2><p>Movi Player stores your playback preferences (such as volume level and resume position) in your browser&#39;s local storage. This data stays on your device and is never transmitted to us.</p><h2 id="chrome-extension-permissions" tabindex="-1">Chrome Extension Permissions <a class="header-anchor" href="#chrome-extension-permissions" aria-label="Permalink to &quot;Chrome Extension Permissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Purpose</th></tr></thead><tbody><tr><td><code>contextMenus</code></td><td>To add a &quot;Play with Movi Player&quot; option when you right-click a video link</td></tr><tr><td><code>activeTab</code></td><td>To detect video URLs on the current page</td></tr><tr><td><code>clipboardRead</code></td><td>To allow pasting video URLs directly into the player</td></tr></tbody></table><p>These permissions are used solely for their stated purpose and grant no access to browsing history, personal data, or any other information.</p><h2 id="third-party-services" tabindex="-1">Third-Party Services <a class="header-anchor" href="#third-party-services" aria-label="Permalink to &quot;Third-Party Services&quot;">​</a></h2><ul><li><strong>Cloudflare</strong> hosts and serves moviplayer.com. Cloudflare processes connection data (including IP addresses) as part of delivering the site.</li><li><strong>Cloudflare Turnstile</strong> protects the comments form and URL playback from bots. It runs invisibly — there is no CAPTCHA to solve and nothing appears on screen. Turnstile processes minimal signals to tell human visitors from automated ones; what those are, and how Cloudflare handles them, is set out in the <a href="https://www.cloudflare.com/turnstile-privacy-policy/" target="_blank" rel="noreferrer">Cloudflare Turnstile Privacy Addendum</a>.</li><li><strong>Google Drive</strong>, if you choose to use that integration, is subject to <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Google&#39;s Privacy Policy</a>. Movi Player&#39;s use of information received from Google APIs adheres to the <a href="https://developers.google.com/terms/api-services-user-data-policy" target="_blank" rel="noreferrer">Google API Services User Data Policy</a>, including the Limited Use requirements.</li></ul><p>We share data with no one else.</p><h2 id="your-rights" tabindex="-1">Your Rights <a class="header-anchor" href="#your-rights" aria-label="Permalink to &quot;Your Rights&quot;">​</a></h2><p>You may request deletion of any comment you have posted, or ask what data associated with you we hold, by writing to the contact address below. Because we operate no accounts and store no viewing history, in most cases the answer is that we hold nothing about you at all.</p><h2 id="open-source" tabindex="-1">Open Source <a class="header-anchor" href="#open-source" aria-label="Permalink to &quot;Open Source&quot;">​</a></h2><p>Movi Player is open source. You can review the entire source code — including the relay and comments code described above — at <a href="https://github.com/MrUjjwalG/movi-player" target="_blank" rel="noreferrer">github.com/MrUjjwalG/movi-player</a>.</p><h2 id="changes-to-this-policy" tabindex="-1">Changes to This Policy <a class="header-anchor" href="#changes-to-this-policy" aria-label="Permalink to &quot;Changes to This Policy&quot;">​</a></h2><p>If we make changes to this privacy policy, we will update the &quot;Last updated&quot; date above.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Privacy questions or deletion requests: <strong><a href="mailto:privacy@moviplayer.com" target="_blank" rel="noreferrer">privacy@moviplayer.com</a></strong>, or open an issue on our <a href="https://github.com/MrUjjwalG/movi-player/issues" target="_blank" rel="noreferrer">GitHub repository</a>.</p>',32)])])}const y=o(s,[["render",i]]);export{p as __pageData,y as default};
